                print(f"[ks3] self-test B{batch} NS{ns} ctx{ctx}{' row0' if row0 else ''}: {'PASS' if ok else 'FAIL'} err {ek:.4e} "
                      f"(r1 {e1:.4e}) cache bytes != r1 {nbad} tickets {tick} repeat identical {same}", flush=True)
