        if proj == "unpooler":
            zb = state.get("v12_zbuf")
            if not (V12_ZBUF and zb is not None and R1_UNPOOL_INTO_ZEROS and tokens <= SLICED_UNPOOL_MAX_TOKENS):
                return None
